await run("recovered read APIs forward cancellation options", async () => {
	const originalFetch = globalThis.fetch;
	const controller = new AbortController();
	const calls = [];
	globalThis.fetch = async (url, options = {}) => {
		calls.push({ url: String(url), options });
		return {
			status: 200,
			ok: true,
			json: async () => [],
			blob: async () => new Blob([]),
		};
	};

	try {
		await bestiaryApi.getBestiarySources({ signal: controller.signal });
		await bestiaryApi.getBestiaryData("all", {
			signal: controller.signal,
		});
		await bestiaryApi.getCustomBestiaryData({
			signal: controller.signal,
			headers: { "X-Test": "custom" },
		});
		await bestiaryApi.getBestiaryFavorites({
			signal: controller.signal,
		});
		await spellApi.getSpellSources({ signal: controller.signal });
		await spellApi.getSpellData("all", {
			signal: controller.signal,
		});
		await spellApi.searchSpells(
			{ name: "shield" },
			{ signal: controller.signal },
		);
		await referenceApi.getConditions({ signal: controller.signal });
		await campaignApi.getEntities(
			"alpha",
			"npc",
			{ signal: controller.signal },
		);
		await sessionApi.listSessions("alpha", {
			signal: controller.signal,
		});
		await sessionApi.getSession(
			"alpha",
			"one.json",
			{ signal: controller.signal },
		);

		assert.equal(calls.length, 11);
		assert.equal(
			calls.every((call) => call.options.signal === controller.signal),
			true,
		);
		const customCall = calls.find((call) =>
			call.url.startsWith("/api/bestiary/custom?"),
		);
		assert.equal(customCall.options.cache, "no-store");
		const customHeaders = new Headers(customCall.options.headers);
		assert.equal(customHeaders.get("Cache-Control"), "no-cache");
		assert.equal(customHeaders.get("X-Test"), "custom");
		assert.equal(isAbortError({ name: "AbortError" }), true);
		assert.equal(isAbortError(new Error("failure")), false);
	} finally {
		globalThis.fetch = originalFetch;
	}
});

await run(
	"recovered campaign search caps concurrency and preserves order",
	async () => {
		let active = 0;
		let maxActive = 0;
		const completed = await mapWithConcurrency(
			[0, 1, 2, 3, 4, 5],
			2,
			async (value) => {
				active += 1;
				maxActive = Math.max(maxActive, active);
				await new Promise((resolve) => setTimeout(resolve, 1));
				active -= 1;
				return value * 2;
			},
		);
		assert.equal(maxActive, 2);
		assert.deepEqual(completed, [0, 2, 4, 6, 8, 10]);

		const controller = new AbortController();
		const sessions = Array.from({ length: 15 }, (_, index) => ({
			fileName: `session-${index}.json`,
		}));
		const seenSignals = [];
		active = 0;
		maxActive = 0;
		const index = await loadCampaignSearchIndex({
			campaign: { slug: "alpha", name: "Alpha" },
			api: {
				getEntities: async (_slug, _type, options) => {
					seenSignals.push(options?.signal);
					return [];
				},
				listSessions: async (_slug, options) => {
					seenSignals.push(options?.signal);
					return sessions;
				},
				getSession: async (_slug, fileName, options) => {
					seenSignals.push(options?.signal);
					const sessionIndex = Number(
						fileName.match(/\d+/)?.[0] || 0,
					);
					active += 1;
					maxActive = Math.max(maxActive, active);
					await new Promise((resolve) =>
						setTimeout(resolve, (sessionIndex % 3) + 1),
					);
					active -= 1;
					return {
						name: `Session ${sessionIndex}`,
						data: {
							notes: [
								{
									id: sessionIndex,
									title: `Note ${sessionIndex}`,
									text: "",
								},
							],
						},
					};
				},
			},
			translate: (key) => key,
			requestOptions: { signal: controller.signal },
		});

		assert.equal(
			maxActive <= CAMPAIGN_SEARCH_SESSION_LOAD_CONCURRENCY,
			true,
		);
		assert.equal(maxActive > 1, true);
		assert.equal(
			seenSignals.every((signal) => signal === controller.signal),
			true,
		);
		assert.deepEqual(
			index
				.filter((item) => item.title.startsWith("Note "))
				.map((item) => item.title),
			sessions.map((_, sessionIndex) => `Note ${sessionIndex}`),
		);
		assert.equal(
			filterCampaignSearchResults(
				Array.from(
					{ length: CAMPAIGN_SEARCH_RESULT_LIMIT + 5 },
					(_, resultIndex) => ({
						id: String(resultIndex),
						filter: "notes",
						title: "Note",
						subtitle: "",
						text: "",
						target: { campaignSlug: "alpha" },
						searchText: "note",
					}),
				),
				"note",
				new Set(CAMPAIGN_SEARCH_FILTERS),
			).length,
			CAMPAIGN_SEARCH_RESULT_LIMIT,
		);
	},
);

await run(
	"FSD import boundaries reject private paths through one language-symmetric baseline",
	async () => {
		const lintImports = (source, patterns) => {
			const linter = new Linter({ configType: "flat" });
			return linter.verify(source, {
				languageOptions: {
					ecmaVersion: "latest",
					sourceType: "module",
				},
				rules: {
					"no-restricted-imports": [
						"error",
						{ patterns },
					],
				},
			});
		};
		const expectRestricted = (source, patterns) => {
			const messages = lintImports(source, patterns);
			assert.ok(messages.length >= 1);
			assert.ok(
				messages.every(
					(message) => message.ruleId === "no-restricted-imports",
				),
			);
		};
		const expectAllowed = (source, patterns) => {
			assert.deepEqual(lintImports(source, patterns), []);
		};

		expectRestricted(
			'import value from "../../../entities/reference/api/referenceApi.ts";',
			[RECOVERED_ENTITY_PUBLIC_API_PATTERN],
		);
		expectRestricted(
			'import value from "../../api/campaignApi.ts";',
			CAMPAIGN_MODEL_IMPORT_PATTERNS,
		);
		expectRestricted(
			'import value from "../../../index.js";',
			CAMPAIGN_MODEL_IMPORT_PATTERNS,
		);
		expectRestricted(
			'import value from "../../../features/editor/ui/Input.tsx";',
			CAMPAIGN_MODEL_IMPORT_PATTERNS,
		);
		expectRestricted(
			'import value from "../../spell/api/spellApi.ts";',
			REFERENCE_LOADER_IMPORT_PATTERNS,
		);
		expectRestricted(
			'import value from "../../../features/rules-reference/model/private.ts";',
			REFERENCE_LOADER_IMPORT_PATTERNS,
		);
		expectRestricted(
			'import value from "../../../entities/bestiary/api/bestiaryApi.ts";',
			FSD_PUBLIC_API_PATTERNS,
		);
		expectRestricted(
			'import value from "./features/ai/model/aiDiff.ts";',
			FSD_PUBLIC_API_PATTERNS,
		);
		expectRestricted(
			'import value from "/src/features/ai/model/aiDiff.ts";',
			FSD_PUBLIC_API_PATTERNS,
		);
		expectRestricted(
			'import value from "../../ai/model/aiDiff.ts";',
			FSD_PUBLIC_API_PATTERNS,
		);
		expectRestricted(
			'import value from "../ai/model/aiDiff.ts";',
			FSD_PUBLIC_API_PATTERNS,
		);
		expectRestricted(
			'import value from "../../campaign/campaignStateUtils";',
			FSD_PUBLIC_API_PATTERNS,
		);
		for (const source of [
			'import { Modal } from "../../../shared/ui/Modal.tsx";',
			'import { ModalView } from "../../../shared/ui/ModalView.tsx";',
			'import { useModalController } from "../../../shared/ui/useModalController.ts";',
			'import { ModalProps } from "../../../shared/ui/modalModel.ts";',
		]) {
			expectRestricted(source, [SHARED_MODAL_PUBLIC_API_PATTERN]);
			expectRestricted(source, TYPESCRIPT_PUBLIC_API_PATTERNS);
		}
		expectAllowed(
			'import value from "../../../entities/session/index.js";',
			FSD_PUBLIC_API_PATTERNS,
		);
		expectAllowed(
			'import value from "./features/ai/index.js";',
			FSD_PUBLIC_API_PATTERNS,
		);
		expectAllowed(
			'import value from "/src/features/ai/index.js";',
			FSD_PUBLIC_API_PATTERNS,
		);
		expectAllowed(
			'import value from "../../ai/ui/index.js";',
			FSD_PUBLIC_API_PATTERNS,
		);
		expectAllowed(
			'import value from "../ai/index.js";',
			FSD_PUBLIC_API_PATTERNS,
		);
		expectAllowed(
			'import value from "../../../entities/reference/model.js";',
			FSD_PUBLIC_API_PATTERNS,
		);
		expectAllowed(
			'import value from "../../../pages/campaign/graph.js";',
			FSD_PUBLIC_API_PATTERNS,
		);
		expectAllowed(
			'import value from "../../model/campaignGraph.ts";',
			FSD_PUBLIC_API_PATTERNS,
		);
		expectAllowed(
			'import value from "../api/referenceApi.ts";',
			REFERENCE_LOADER_IMPORT_PATTERNS,
		);
		expectAllowed(
			'import { Modal } from "../../../shared/ui/index.js";',
			[SHARED_MODAL_PUBLIC_API_PATTERN],
		);
		for (const pattern of FSD_PUBLIC_API_PATTERNS) {
			assert.ok(TYPESCRIPT_PUBLIC_API_PATTERNS.includes(pattern));
		}
		assert.ok(
			TYPESCRIPT_PUBLIC_API_PATTERNS.includes(
				SHARED_MODAL_PUBLIC_API_PATTERN,
			),
		);

		for (const [layer, expectedNames] of Object.entries(FSD_SLICE_NAMES)) {
			const entries = await fs.readdir(path.join("src", layer), {
				withFileTypes: true,
			});
			const actualNames = entries
				.filter((entry) => entry.isDirectory())
				.map((entry) => entry.name)
				.sort();
			assert.deepEqual(actualNames, [...expectedNames]);
		}

		const eslintSource = await fs.readFile("eslint.config.js", "utf8");
		assert.match(
			eslintSource,
			/import \{\s*CAMPAIGN_MODEL_IMPORT_PATTERNS,\s*FSD_BOUNDARY_PLUGIN,\s*FSD_PUBLIC_API_PATTERNS,/,
		);
		assert.match(
			eslintSource,
			/patterns: \[\s*\.\.\.FSD_PUBLIC_API_PATTERNS,/,
		);
		assert.match(
			eslintSource,
			/\.\.\.FSD_PUBLIC_API_PATTERNS,\s*SHARED_MODAL_PUBLIC_API_PATTERN,/,
		);
		assert.doesNotMatch(eslintSource, /features\/modal/);
		assert.match(
			eslintSource,
			/files: \['\*\*\/\*\.\{js,jsx,ts,tsx\}'\],\s*ignores: \['src\/\*\*\/\*\.\{js,jsx,ts,tsx\}'\],\s*rules: \{\s*'no-restricted-imports': 'off',/,
		);
	},
);

