const FSD_RULES_REFERENCE_STORE_FACADE_RULE_ID =
	"fsd-boundaries/rules-reference-store-facade";
const FSD_AI_STORE_FACADE_RULE_ID = "fsd-boundaries/ai-store-facade";
const FSD_EDITOR_STORE_FACADE_RULE_ID =
	"fsd-boundaries/editor-store-facade";
const FSD_DICE_STORE_FACADE_RULE_ID = "fsd-boundaries/dice-store-facade";
const FSD_IMAGES_STORE_FACADE_RULE_ID = "fsd-boundaries/images-store-facade";
const FSD_CAMPAIGN_ENTITY_CARD_STORE_FACADE_RULE_ID =
	"fsd-boundaries/campaign-entity-card-store-facade";
const FSD_CAMPAIGN_SEARCH_STORE_FACADE_RULE_ID =
	"fsd-boundaries/campaign-search-store-facade";
const FSD_CAMPAIGN_ENTITY_MODAL_STORE_FACADE_RULE_ID =
	"fsd-boundaries/campaign-entity-modal-store-facade";
const FSD_RULES_REFERENCE_MODAL_STORE_FACADE_RULE_ID =
	"fsd-boundaries/rules-reference-modal-store-facade";
const FSD_SPELLS_BROWSER_STORE_FACADE_RULE_ID =
	"fsd-boundaries/spells-browser-store-facade";
const FSD_MONSTER_STAT_BLOCK_STORE_FACADE_RULE_ID =
	"fsd-boundaries/monster-stat-block-store-facade";
const FSD_SIDEBAR_STORE_FACADE_RULE_ID =
	"fsd-boundaries/sidebar-store-facade";
const FSD_BESTIARY_BROWSER_STORE_FACADE_RULE_ID =
	"fsd-boundaries/bestiary-browser-store-facade";
const FSD_AI_ASSISTANT_STORE_FACADE_RULE_ID =
	"fsd-boundaries/ai-assistant-store-facade";
const FSD_CAMPAIGN_PAGE_STORE_FACADE_RULE_ID =
	"fsd-boundaries/campaign-page-store-facade";
const FSD_SESSION_PAGE_STORE_FACADE_RULE_ID =
	"fsd-boundaries/session-page-store-facade";
const FSD_ENCOUNTER_PAGE_STORE_FACADE_RULE_ID =
	"fsd-boundaries/encounter-page-store-facade";

function lintFsdBoundaryRule(
	source,
	fileName,
	ruleId,
	plugin = FSD_BOUNDARY_PLUGIN,
) {
	const linter = new Linter({ configType: "flat" });
	return linter.verify(
		source,
		{
			files: ["**/*.{js,jsx,ts,tsx}"],
			languageOptions: {
				ecmaVersion: "latest",
				sourceType: "module",
			},
			plugins: {
				"fsd-boundaries": plugin,
			},
			rules: {
				[ruleId]: "error",
			},
		},
		{ filename: path.resolve(fileName) },
	);
}

function lintFsdSameLayerEdges(source, fileName) {
	return lintFsdBoundaryRule(source, fileName, FSD_SAME_LAYER_RULE_ID);
}

function lintFsdSameLayerEdgesWithBaseline(source, fileName, baseline) {
	return lintFsdBoundaryRule(
		source,
		fileName,
		FSD_SAME_LAYER_RULE_ID,
		{
			rules: {
				"same-layer-file-edges":
					createFsdSameLayerFileEdgeRule(baseline),
			},
		},
	);
}

function lintFsdPublicEntries(source, fileName) {
	return lintFsdBoundaryRule(source, fileName, FSD_PUBLIC_ENTRY_RULE_ID);
}

function isFsdSourceFile(entry) {
	return entry.isFile() && /\.(?:js|jsx|ts|tsx)$/.test(entry.name);
}

async function collectFsdSourceFiles(directory) {
	const entries = await fs.readdir(directory, { withFileTypes: true });
	const files = [];
	for (const entry of entries) {
		const entryPath = path.join(directory, entry.name);
		if (entry.isDirectory()) {
			files.push(...(await collectFsdSourceFiles(entryPath)));
		}
		if (isFsdSourceFile(entry)) {
			files.push(entryPath.replace(/\\/g, "/"));
		}
	}
	return files;
}

function readFsdSpecifierMatches(source, codeMask, pattern) {
	return Array.from(source.matchAll(pattern))
		.filter((match) => codeMask[match.index] !== " ")
		.map((match) => match[1]);
}

const FSD_COMMENT_OR_LITERAL_PATTERN =
	/("(?:\\[\s\S]|[^"\\])*"|'(?:\\[\s\S]|[^'\\])*'|`(?:\\[\s\S]|[^`\\])*`)|\/\/[^\r\n]*|\/\*[\s\S]*?\*\//g;

function createFsdCodeMask(source) {
	return source.replace(
		FSD_COMMENT_OR_LITERAL_PATTERN,
		(match) => match.replace(/[^\r\n]/g, " "),
	);
}

function readStaticFsdSpecifiers(source) {
	const codeMask = createFsdCodeMask(source);
	return [
		...readFsdSpecifierMatches(
			source,
			codeMask,
			/\bfrom\s*["']([^"']+)["']/g,
		),
		...readFsdSpecifierMatches(
			source,
			codeMask,
			/\bimport\s*["']([^"']+)["']/g,
		),
		...readFsdSpecifierMatches(
			source,
			codeMask,
			/\b(?:import|require)\s*\(\s*["']([^"']+)["']/g,
		),
		...readFsdSpecifierMatches(
			source,
			codeMask,
			/\b(?:import|require)\s*\(\s*`([^`]*)`/g,
		),
	].filter((specifier) => !specifier.includes("${"));
}

function getCataloguedTestSiblingSlice(layer, sourceSlice, targetSlice) {
	if (targetSlice === sourceSlice) return null;
	return FSD_SLICE_NAMES[layer].includes(targetSlice) ? targetSlice : null;
}

function resolveTestModuleSpecifierPath(filePath, specifier) {
	const [cleanSpecifier] = specifier
		.replaceAll("\\", "/")
		.split(/[?#]/);
	if (cleanSpecifier.startsWith("/src/")) {
		return path.posix.normalize(cleanSpecifier).slice(1);
	}
	if (!cleanSpecifier.startsWith(".")) return null;
	return path.posix.normalize(
		path.posix.join(path.posix.dirname(filePath), cleanSpecifier),
	);
}

function resolveTestSameLayerTarget(filePath, layer, sourceSlice, specifier) {
	const resolved = resolveTestModuleSpecifierPath(filePath, specifier);
	if (!resolved) return null;
	const [root, resolvedLayer, targetSlice] = resolved.split("/");
	if (root !== "src") return null;
	if (resolvedLayer !== layer) return null;
	return getCataloguedTestSiblingSlice(layer, sourceSlice, targetSlice);
}

async function getActualSameLayerTargets(filePath, layer) {
	const sourceSlice = filePath.split("/")[2];
	const source = await fs.readFile(filePath, "utf8");
	const targets = new Set();
	for (const specifier of readStaticFsdSpecifiers(source)) {
		const targetSlice = resolveTestSameLayerTarget(
			filePath,
			layer,
			sourceSlice,
			specifier,
		);
		if (targetSlice) targets.add(targetSlice);
	}
	return [...targets].sort();
}

async function getActualSameLayerEntries(layer) {
	const sourceFiles = await collectFsdSourceFiles(path.join("src", layer));
	const actualEntries = [];
	for (const filePath of sourceFiles) {
		const targets = await getActualSameLayerTargets(filePath, layer);
		if (targets.length > 0) actualEntries.push([filePath, targets]);
	}
	return actualEntries.sort(([left], [right]) => left.localeCompare(right));
}

async function countActualSameLayerDeclarations(layer) {
	const sourceFiles = await collectFsdSourceFiles(path.join("src", layer));
	let declarationCount = 0;
	for (const filePath of sourceFiles) {
		const sourceSlice = filePath.split("/")[2];
		const source = await fs.readFile(filePath, "utf8");
		for (const specifier of readStaticFsdSpecifiers(source)) {
			if (
				resolveTestSameLayerTarget(
					filePath,
					layer,
					sourceSlice,
					specifier,
				)
			) {
				declarationCount += 1;
			}
		}
	}
	return declarationCount;
}

async function assertSameLayerBaselineShape(layer, expectedCounts) {
	const entries = FSD_SAME_LAYER_FILE_EDGE_BASELINE[layer];
	const pairs = new Set();
	let edgeCount = 0;
	assert.ok(Object.isFrozen(entries));
	for (const [filePath, targetSlices] of Object.entries(entries)) {
		assert.ok(Object.isFrozen(targetSlices));
		assert.deepEqual(targetSlices, [...new Set(targetSlices)].sort());
		assert.match(
			filePath,
			new RegExp(`^src/${layer}/[^/]+/.+\\.(?:js|jsx|ts|tsx)$`),
		);
		await fs.access(filePath);
		const sourceSlice = filePath.split("/")[2];
		for (const targetSlice of targetSlices) {
			assert.ok(FSD_SLICE_NAMES[layer].includes(targetSlice));
			assert.notEqual(targetSlice, sourceSlice);
			pairs.add(`${sourceSlice}->${targetSlice}`);
			edgeCount += 1;
		}
	}
	assert.equal(Object.keys(entries).length, expectedCounts.importers);
	assert.equal(edgeCount, expectedCounts.edges);
	assert.equal(pairs.size, expectedCounts.pairs);
	assert.equal(
		await countActualSameLayerDeclarations(layer),
		expectedCounts.declarations,
	);
}

function getRequiredSourceMatch(source, pattern, message = String(pattern)) {
	const match = source.match(pattern);
	assert.ok(match, message);
	return match[0];
}

async function getEncounterPageCompositionSource() {
	const [displayProjectionSource, controllerSource, participantEditingSource, workflowsSource, contentSource] = await Promise.all([
		fs.readFile(
			"src/pages/encounter/model/useEncounterPageDisplayProjection.ts",
			"utf8",
		),
		fs.readFile(
			"src/pages/encounter/model/useEncounterPageController.ts",
			"utf8",
		),
		fs.readFile(
			"src/pages/encounter/model/useEncounterPageParticipantEditing.ts",
			"utf8",
		),
		fs.readFile(
			"src/pages/encounter/model/useEncounterMonsterAiWorkflows.ts",
			"utf8",
		),
		fs.readFile(
			"src/pages/encounter/ui/components/EncounterPageContent.tsx",
			"utf8",
		),
	]);
	return `${displayProjectionSource}\n${controllerSource}\n${participantEditingSource}\n${workflowsSource}\n${contentSource}`;
}

async function getEncounterPrivateComponentSources(componentName) {
	const [encounterSource, componentSource, runtimeEntrySource, typeEntrySource] =
		await Promise.all([
			getEncounterPageCompositionSource(),
			fs.readFile(
				`src/pages/encounter/ui/components/${componentName}.tsx`,
				"utf8",
			),
			fs.readFile("src/pages/encounter/index.js", "utf8"),
			fs.readFile("src/pages/encounter/index.d.ts", "utf8"),
		]);
	return { encounterSource, componentSource, runtimeEntrySource, typeEntrySource };
}

