function assertEncounterPrivateComponentBoundary({
	componentName,
	encounterSource,
	rawDefinitionPattern,
	runtimeEntrySource,
	typeEntrySource,
}) {
	assert.match(
		encounterSource,
		new RegExp(
			`import ${componentName} from "\\./(?:components/)?${componentName}\\.tsx";`,
		),
	);
	assert.doesNotMatch(encounterSource, rawDefinitionPattern);
	assert.doesNotMatch(
		`${runtimeEntrySource}\n${typeEntrySource}`,
		new RegExp(componentName),
	);
}

function getRequiredSourceSlice(source, startToken, endToken) {
	const startIndex = source.indexOf(startToken);
	const endIndex = source.indexOf(endToken, startIndex);
	assert.ok(startIndex >= 0, startToken);
	assert.ok(endIndex > startIndex, endToken);
	return source.slice(startIndex, endIndex);
}

function readSourceJsxPropNames(tagSource) {
	return Array.from(
		tagSource.matchAll(/\s+([A-Za-z][A-Za-z0-9]*)=(?:\{|\")/g),
		(match) => match[1],
	);
}

function assertSourceTokensInOrder(source, tokens, contractName) {
	const normalizedSource = source.replace(/\r\n/g, "\n");
	let previousIndex = -1;
	for (const token of tokens) {
		const tokenIndex = normalizedSource.indexOf(
			token.replace(/\r\n/g, "\n"),
			previousIndex + 1,
		);
		assert.ok(
			tokenIndex > previousIndex,
			`${token} must retain ${contractName} order`,
		);
		previousIndex = tokenIndex;
	}
}

function assertPublicTypeSurface(entrySource, publicTypes) {
	for (const publicType of publicTypes) {
		assert.match(entrySource, new RegExp(`\\b${publicType}\\b`));
	}
}

function assertExportedInterfaceFragments(
	source,
	interfaceName,
	requiredFragments,
) {
	const match = source.match(
		new RegExp(
			`export interface ${interfaceName}(?: extends [^{]+)? \\{([\\s\\S]*?)\\n\\}`,
		),
	);
	assert.ok(match);
	for (const fragment of requiredFragments) {
		assert.ok(
			match[1].includes(fragment),
			`${interfaceName} must preserve ${fragment}`,
		);
	}
}

function assertNoSiblingWidgetImportsInSource(filePath, source, slice) {
	const siblingWidgetImports = readStaticFsdSpecifiers(source)
		.map((specifier) => [
			specifier,
			resolveTestModuleSpecifierPath(filePath, specifier),
		])
		.filter(
			([, resolved]) =>
				resolved?.startsWith("src/widgets/") &&
				!resolved.startsWith(`${slice}/`),
		);
	assert.deepEqual(
		siblingWidgetImports,
		[],
		`${filePath} must not import a sibling widget`,
	);
}

async function assertNoSiblingWidgetImports(slice) {
	for (const filePath of await collectFsdSourceFiles(slice)) {
		const source = await fs.readFile(filePath, "utf8");
		assertNoSiblingWidgetImportsInSource(filePath, source, slice);
	}
}

function assertReferenceOwnerComposition(source, owner, beforeToken) {
	const rulesBinding = getRequiredSourceMatch(
		source,
		new RegExp(
			`const ${owner}RulesReferenceContent =\\s*createRulesReferenceModalContentComponent\\(\\{[\\s\\S]*?\\}\\);`,
		),
	);
	const editorBinding = getRequiredSourceMatch(
		source,
		new RegExp(
			`const ${owner}MonsterEditorModal = createMonsterEditorModalComponent\\(\\{[\\s\\S]*?\\}\\);`,
		),
	);
	assert.deepEqual(
		Array.from(
			rulesBinding.matchAll(/^\s+([A-Za-z][A-Za-z0-9]*),$/gm),
			(match) => match[1],
		),
		["MonsterStatBlock", "SpellsBrowser"],
	);
	assert.match(
		editorBinding,
		new RegExp(`\\bRulesReferenceContent: ${owner}RulesReferenceContent,`),
	);
	const beforeIndex = source.indexOf(beforeToken);
	assert.ok(source.indexOf(rulesBinding) < source.indexOf(editorBinding));
	assert.ok(source.indexOf(editorBinding) < beforeIndex);
	assert.equal(
		(source.match(/createRulesReferenceModalContentComponent\(/g) || []).length,
		1,
	);
	assert.equal(
		(source.match(/createMonsterEditorModalComponent\(/g) || []).length,
		1,
	);
	assert.match(
		source,
		new RegExp(`\\bMonsterEditorModal: ${owner}MonsterEditorModal,`),
	);
}

function inspectFsdBoundaryVisitor(ruleName, fileName, visitorName, node) {
	const reports = [];
	const listeners = FSD_BOUNDARY_PLUGIN.rules[ruleName].create({
		getFilename: () => path.resolve(fileName),
		report: (report) => reports.push(report),
	});
	listeners[visitorName](node);
	return reports;
}

await run(
	"FSD public-entry rule closes non-static-import syntax gaps",
	async () => {
		const importer = "src/features/ai/ui/AiAssistantShell.tsx";
		for (const source of [
			'import { ImageGallery } from "../../images/ui/Private.tsx";',
			'export { ImageGallery } from "../../images/ui/Private.tsx";',
			'export * from "../../images/ui/Private.tsx";',
			'const lazyImages = import("../../images/ui/Private.tsx");',
			'const commonImages = require("../../images/ui/Private.tsx");',
			'const templateImages = import(`../../images/ui/Private.tsx`);',
			'import.meta.glob("../../images/ui/Private.tsx");',
			'import.meta.glob(["../../images/ui/*.tsx"]);',
			'const rootImages = import("/src/features/images/ui/Private.tsx");',
			'const traversedRootImages = import("/src/features/ai/../images/ui/Private.tsx");',
			'const windowsImages = require("../../images\\\\ui\\\\Private.tsx");',
			'const implicitEntry = import("../../images");',
		]) {
			const messages = lintFsdPublicEntries(source, importer);
			assert.equal(messages.length, 1, source);
			assert.equal(messages[0].ruleId, FSD_PUBLIC_ENTRY_RULE_ID);
			assert.match(messages[0].message, /public entry of features\/images/);
		}

		for (const source of [
			'import { ImageGallery } from "../../images/index.js";',
			'const lazyImages = import("../../images/ui/index.ts");',
			'const imagesModel = require("../../images/model.js?worker");',
			'import value from "../model/privateAiModel.ts";',
			'import packageValue from "features/images/ui/private";',
			'const dynamic = import(`../../${slice}/ui/Private.tsx`);',
		]) {
			assert.deepEqual(lintFsdPublicEntries(source, importer), [], source);
		}

		const rootMessages = lintFsdPublicEntries(
			'import("./features/images/ui/Private.tsx");',
			"src/App.tsx",
		);
		assert.equal(rootMessages.length, 1);
		assert.match(rootMessages[0].message, /features\/images/);

		for (const [visitorName, node] of [
			[
				"TSImportType",
				{
					source: {
						type: "Literal",
						value: "../../images/ui/Private.tsx",
					},
				},
			],
			[
				"TSImportType",
				{
					argument: {
						type: "TSLiteralType",
						literal: {
							type: "Literal",
							value: "../../images/ui/Private.tsx",
						},
					},
				},
			],
			[
				"TSExternalModuleReference",
				{
					expression: {
						type: "Literal",
						value: "../../images/ui/Private.tsx",
					},
				},
			],
		]) {
			const reports = inspectFsdBoundaryVisitor(
				"public-entry-imports",
				importer,
				visitorName,
				node,
			);
			assert.equal(reports.length, 1);
			assert.equal(reports[0].messageId, "privateEntry");
			assert.equal(reports[0].data.slice, "images");
		}
	},
);

await run(
	"same-layer FSD rule rejects growth and reports synthetic stale allowances",
	async () => {
		const auditedImporter =
			"src/features/ai/ui/AiAttachmentControls.tsx";
		const productionViolation = lintFsdSameLayerEdges(
			'import { ImageGallery } from "../../images/index.js";',
			auditedImporter,
		);
		assert.equal(productionViolation.length, 1);
		assert.equal(productionViolation[0].ruleId, FSD_SAME_LAYER_RULE_ID);
		assert.match(productionViolation[0].message, /dependency on "images"/);

		const syntheticBaseline = {
			features: {
				[auditedImporter]: ["images"],
			},
			widgets: {},
		};
		assert.deepEqual(
			lintFsdSameLayerEdgesWithBaseline(
				'import { ImageGallery } from "../../images/index.js";',
				auditedImporter,
				syntheticBaseline,
			),
			[],
		);

		const unexpectedTarget = lintFsdSameLayerEdgesWithBaseline(
			[
				'import { ImageGallery } from "../../images/index.js";',
				'import { Input } from "../../editor/ui/index.js";',
			].join("\n"),
			auditedImporter,
			syntheticBaseline,
		);
		assert.equal(unexpectedTarget.length, 1);
		assert.equal(unexpectedTarget[0].ruleId, FSD_SAME_LAYER_RULE_ID);
		assert.match(unexpectedTarget[0].message, /dependency on "editor"/);

		const unexpectedImporter = lintFsdSameLayerEdges(
			'import { ImageGallery } from "../../images/index.js";',
			"src/features/ai/ui/NewAiPanel.tsx",
		);
		assert.equal(unexpectedImporter.length, 1);
		assert.match(
			unexpectedImporter[0].message,
			/newaipanel\.tsx may not add/,
		);
		for (const source of [
			'const lazyImages = import(`../../images/index.js`);',
			'const commonImages = require(`../../images/index.js`);',
			'import { ImageGallery } from "/src/features/images/index.js";',
			'import { ImageGallery } from "/src/features/ai/../images/index.js";',
		]) {
			const messages = lintFsdSameLayerEdges(
				source,
				"src/features/ai/ui/NewAiPanel.tsx",
			);
			assert.equal(messages.length, 1);
			assert.match(messages[0].message, /dependency on "images"/);
		}

		const syntheticStaleAllowance = lintFsdSameLayerEdgesWithBaseline(
			"export const value = 1;",
			auditedImporter,
			syntheticBaseline,
		);
		assert.equal(syntheticStaleAllowance.length, 1);
		assert.match(
			syntheticStaleAllowance[0].message,
			/stale same-layer dependency allowance "images"/,
		);

		assert.deepEqual(
			lintFsdSameLayerEdgesWithBaseline(
				[
					'import { ImageGallery } from "../../images/index.js";',
					'import { ImageAssetField } from "../../images/index.js";',
				].join("\n"),
				auditedImporter,
				syntheticBaseline,
			),
			[],
		);
		assert.deepEqual(
			lintFsdSameLayerEdgesWithBaseline(
				[
					'export { ImageGallery } from "../../images/index.js";',
					'const lazyImages = import("../../images/index.js");',
					'const commonImages = require("../../images/index.js");',
				].join("\n"),
				auditedImporter,
				syntheticBaseline,
			),
			[],
		);
		assert.deepEqual(
			lintFsdSameLayerEdges(
				[
					'import value from "../model/aiModel.js";',
					'import { bestiaryApi } from "../../../entities/bestiary/index.js";',
				].join("\n"),
				"src/features/ai/ui/NewAiModelConsumer.ts",
			),
			[],
		);
	},
);

await run(
	"same-layer FSD baseline exactly matches the remaining source graph",
	async () => {
		assert.ok(Object.isFrozen(FSD_SAME_LAYER_FILE_EDGE_BASELINE));
		assert.deepEqual(
			readStaticFsdSpecifiers(
				[
					'// import "../../editor/index.js";',
					'/* const hidden = require("../../editor/index.js"); */',
					'const example = \'import("../../editor/index.js")\';',
					'import { ImageGallery } from "../../images/index.js";',
				].join("\n"),
			),
			["../../images/index.js"],
		);
		await assertSameLayerBaselineShape("features", {
			importers: 0,
			edges: 0,
			pairs: 0,
			declarations: 0,
		});
		await assertSameLayerBaselineShape("widgets", {
			importers: 0,
			edges: 0,
			pairs: 0,
			declarations: 0,
		});

		for (const layer of ["features", "widgets"]) {
			const actualEntries = await getActualSameLayerEntries(layer);
			const expectedEntries = Object.entries(
				FSD_SAME_LAYER_FILE_EDGE_BASELINE[layer],
			).sort(([left], [right]) => left.localeCompare(right));
			assert.deepEqual(actualEntries, expectedEntries);
		}

		const eslintSource = await fs.readFile("eslint.config.js", "utf8");
		assert.match(
			eslintSource,
			/'src\/features\/\*\*\/\*\.\{js,jsx,ts,tsx\}',\s*'src\/widgets\/\*\*\/\*\.\{js,jsx,ts,tsx\}',/,
		);
		assert.match(
			eslintSource,
			/files: \['src\/\*\*\/\*\.\{js,jsx,ts,tsx\}'\],\s*plugins: \{\s*'fsd-boundaries': FSD_BOUNDARY_PLUGIN,/,
		);
		assert.match(
			eslintSource,
			/'fsd-boundaries\/public-entry-imports': 'error'/,
		);
		assert.match(
			eslintSource,
			/'fsd-boundaries\/same-layer-file-edges': 'error'/,
		);
	},
);

await run(
	"Phase 124 moves generic modal ownership to shared and app layers",
	async () => {
		await assert.rejects(
			() => fs.access("src/features/modal"),
			(error) => error?.code === "ENOENT",
		);

		const [
			appSource,
			messageBoxHostSource,
			modalSource,
			modalModelSource,
			runtimeBarrel,
			declarationBarrel,
			eslintSource,
		] = await Promise.all([
			fs.readFile("src/App.tsx", "utf8"),
			fs.readFile("src/app/ui/MessageBoxHost.tsx", "utf8"),
			fs.readFile("src/shared/ui/Modal.tsx", "utf8"),
			fs.readFile("src/shared/ui/modalModel.ts", "utf8"),
			fs.readFile("src/shared/ui/index.js", "utf8"),
			fs.readFile("src/shared/ui/index.d.ts", "utf8"),
			fs.readFile("eslint.config.js", "utf8"),
		]);

		assert.match(
			runtimeBarrel,
			/export \{ default as Modal \} from "\.\/Modal\.tsx";/,
		);
		assert.match(
			declarationBarrel,
			/export \{\s*default as Modal,\s*type ModalProps,?\s*\} from "\.\/Modal\.tsx";/,
		);
		assert.match(
			modalSource,
			/export type \{ ModalProps \} from "\.\/modalModel\.ts";/,
		);
		assert.match(modalSource, /from "\.\/modalModel\.ts"/);
		assert.doesNotMatch(
			modalModelSource,
			/\b(?:createModalApi|formatModalStatusMessage|ModalApi\w*)\b/,
		);
		assert.match(
			messageBoxHostSource,
			/export default function MessageBoxHost\(/,
		);
		assert.match(messageBoxHostSource, /<Modal\b/);
		assert.match(
			appSource,
			/import MessageBoxHost from "\.\/app\/ui\/MessageBoxHost\.tsx";/,
		);
		assert.match(appSource, /<MessageBoxHost\s*\/>/);
		assert.doesNotMatch(appSource, /<MessageBox\s*\/>/);
		assert.match(eslintSource, /\bSHARED_MODAL_PUBLIC_API_PATTERN\b/);
		assert.doesNotMatch(eslintSource, /features\/modal/);

		const sourceFiles = await collectFsdSourceFiles("src");
		const legacyModalImports = [];
		const runtimeModalConsumers = [];
		const namedImportPattern =
			/import\s*\{([\s\S]*?)\}\s*from\s*["']([^"']+)["']/g;
		for (const filePath of sourceFiles) {
			const source = await fs.readFile(filePath, "utf8");
			const codeMask = createFsdCodeMask(source);
			for (const specifier of readStaticFsdSpecifiers(source)) {
				const resolved = resolveTestModuleSpecifierPath(filePath, specifier);
				if (
					resolved === "src/features/modal" ||
					resolved?.startsWith("src/features/modal/")
				) {
					legacyModalImports.push([filePath, specifier]);
				}
			}
			if (!/<Modal(?:\s|>)/.test(codeMask)) continue;
			const imports = Array.from(source.matchAll(namedImportPattern))
				.filter((match) => codeMask[match.index] !== " ")
				.filter((match) => /\bModal\b/.test(match[1]))
				.map((match) => match[2]);
			runtimeModalConsumers.push([filePath, imports]);
		}

		assert.deepEqual(legacyModalImports, []);
		assert.ok(runtimeModalConsumers.length > 0);
		for (const [filePath, imports] of runtimeModalConsumers) {
			assert.deepEqual(
				imports.map((specifier) =>
					resolveTestModuleSpecifierPath(filePath, specifier),
				),
				["src/shared/ui/index.js"],
				`${filePath} must import Modal through shared/ui`,
			);
		}
	},
);

