		assert.match(
			monsterTags[1],
			/editOptions\s*\? \(monster\) =>\s*openCreatureFieldEdit\(editOptions\.resource, monster, \{\s*mode: "encounter-participant",\s*participantKey: editOptions\.participantKey,\s*\}\)\s*: undefined/,
		);
