		assert.ok(stateHookIndex >= 0);
		assert.ok(draftHookIndex > stateHookIndex);
		assert.ok(nullGuardIndex > draftHookIndex);
		assert.ok(viewIndex > nullGuardIndex);
		assert.ok(editorIndex > viewIndex);

