await run(
	"AI system instruction policies preserve section order modes and exclusions",
	() => {
		const assertSectionOrder = (instruction, markers) => {
			let previousIndex = -1;
			for (const marker of markers) {
				const index = instruction.indexOf(marker);
				assert.ok(index > previousIndex, `${marker} must follow prior sections`);
				previousIndex = index;
			}
		};
		const sceneInstruction = buildSystemInstruction({
			useKey: "scene",
			responseLanguage: { label: "Українська" },
			usesStructuredJsonContract: true,
			simplifiedNotesEnabled: true,
			effectiveParseAIResponse: true,
			npcGenerationEnabled: true,
			locationGenerationEnabled: true,
			encounterGenerationEnabled: true,
			customMonsterGenerationEnabled: true,
			characterGenerationEnabled: true,
			entityTargetScope: "mixed",
			globalBasePrompt: "  Темне фентезі  ",
			campaignBasePrompt: "  Низька магія  ",
		});
		assertSectionOrder(sceneInstruction, [
			"MANDATORY LANGUAGE RULE",
			"NAME LANGUAGE RULE",
			"CHARACTER LEVEL CONTRACT",
			"APP MARKDOWN FORMAT CONTRACT",
			"PARSED JSON RESPONSE CONTRACT",
			"OPERATION TARGET IDENTITY RULE",
			"SIMPLIFIED NOTES MODE IS ENABLED",
			"APP ENTITY MENTION RULE",
			"GENERATED NPC DETAIL RULE",
			"GENERATED LOCATION DETAIL RULE",
			"SCENE COMBAT MECHANICS RULE",
			"ENCOUNTER-SCENE LINK RULE",
			"SCENE DATA CONTRACT",
			"SESSION NOTES CONTRACT",
			"ENTITY GENERATION TOGGLES ARE ADDITIVE",
			"Encounter generation is enabled",
			"Custom monster generation is enabled, but official",
			"Character generation is enabled",
			"NPC generation is enabled",
			"Location/faction generation is enabled",
			"ENTITY SCOPE: This session request may create both",
			"SESSION ENTITY SCOPE DECISION RULE",
			"SESSION/CAMPAIGN ENTITY OUTPUT RULE",
			"USER BASE PROMPTS",
		]);
		assert.match(sceneInstruction, /GLOBAL BASE PROMPT:\nТемне фентезі/);
		assert.match(sceneInstruction, /CAMPAIGN BASE PROMPT:\nНизька магія/);
		assert.doesNotMatch(sceneInstruction, /Encounter generation is disabled/);

		const disabledScene = buildSystemInstruction({
			useKey: "scene",
			responseLanguage: { label: "Ukrainian" },
			usesStructuredJsonContract: false,
			effectiveParseAIResponse: false,
			npcGenerationEnabled: false,
			locationGenerationEnabled: false,
			encounterGenerationEnabled: false,
			characterGenerationEnabled: false,
			entityTargetScope: "session",
		});
		assert.match(disabledScene, /Encounter generation is disabled/);
		assert.match(disabledScene, /Character generation is disabled/);
		assert.match(disabledScene, /NPC generation is disabled/);
		assert.match(disabledScene, /Location\/faction generation is disabled/);
		assert.match(
			disabledScene,
			/ENTITY SCOPE: "npc" and "location" operations are session-scoped/,
		);
		assert.doesNotMatch(disabledScene, /PARSED JSON RESPONSE CONTRACT/);
		assert.doesNotMatch(disabledScene, /GENERATED NPC DETAIL RULE/);
		assert.doesNotMatch(disabledScene, /SCENE DATA CONTRACT/);
		assert.doesNotMatch(disabledScene, /SESSION ENTITY SCOPE DECISION RULE/);

		const campaignScopedScene = buildSystemInstruction({
			useKey: "scene",
			responseLanguage: { label: "Ukrainian" },
			effectiveParseAIResponse: true,
			entityTargetScope: "campaign",
		});
		assert.match(
			campaignScopedScene,
			/ENTITY SCOPE: "npc" and "location" operations are campaign-scoped/,
		);
		assert.doesNotMatch(
			campaignScopedScene,
			/SESSION ENTITY SCOPE DECISION RULE/,
		);

		const customMonsterInstruction = buildSystemInstruction({
			useKey: "custom-monster",
			responseLanguage: { label: "Українська" },
			usesStructuredJsonContract: true,
			simplifiedNotesEnabled: true,
		});
		assert.match(customMonsterInstruction, /CUSTOM MONSTER TEXT RULE/);
		assert.match(customMonsterInstruction, /SIMPLIFIED NOTES MODE IS ENABLED/);
		assert.doesNotMatch(customMonsterInstruction, /APP ENTITY MENTION RULE/);

		const encounterEnabled = buildSystemInstruction({
			useKey: "encounter",
			responseLanguage: { label: "English" },
			customMonsterGenerationEnabled: true,
		});
		const encounterDisabled = buildSystemInstruction({
			useKey: "encounter",
			responseLanguage: { label: "English" },
			customMonsterGenerationEnabled: false,
		});
		assert.match(
			encounterEnabled,
			/Custom monster generation is enabled for this encounter/,
		);
		assert.doesNotMatch(encounterEnabled, /Custom monster generation is disabled/);
		assert.match(encounterDisabled, /Custom monster generation is disabled/);
		assert.doesNotMatch(
			encounterDisabled,
			/Custom monster generation is enabled for this encounter/,
		);

		const promptInstruction = buildSystemInstruction({
			useKey: "prompt",
			responseLanguage: { label: "Українська" },
			globalBasePrompt: "",
			campaignBasePrompt: "  Київська кампанія  ",
		});
		assert.ok(promptInstruction.startsWith(systemInstructions.prompt));
		assertSectionOrder(promptInstruction, [
			"MANDATORY LANGUAGE RULE",
			"IMAGE PROMPT LANGUAGE EXCEPTION",
			"USER BASE PROMPTS",
		]);
		assert.match(promptInstruction, /GLOBAL BASE PROMPT:\n\(none\)/);
		assert.match(
			promptInstruction,
			/CAMPAIGN BASE PROMPT:\nКиївська кампанія/,
		);

		const imageInstruction = buildSystemInstruction({
			useKey: "image",
			globalBasePrompt: "  Загальний стиль  ",
			imagePromptBasePrompt: "  Oil painting  ",
		});
		assert.ok(imageInstruction.startsWith(systemInstructions.image));
		assertSectionOrder(imageInstruction, [
			"USER BASE PROMPTS",
			"IMAGE PROMPT BASE STYLE",
			"Oil painting",
		]);
		assert.doesNotMatch(imageInstruction, /MANDATORY LANGUAGE RULE/);

		const fallbackInstruction = buildSystemInstruction({
			useKey: "unknown-mode",
			responseLanguage: { label: "Українська" },
		});
		assert.ok(fallbackInstruction.startsWith(systemInstructions.prompt));
		assert.match(fallbackInstruction, /MANDATORY LANGUAGE RULE/);
		assert.doesNotMatch(fallbackInstruction, /IMAGE PROMPT LANGUAGE EXCEPTION/);
	},
);

await run("Gemini gateway owns SDK request shaping and refreshes changed keys", async () => {
	let apiKey = "first";
	const createdKeys = [];
	const modelConfigs = [];
	const requestPayloads = [];
	const gateway = createGeminiGateway({
		getApiKey: () => apiKey,
		createClient: (key) => {
			createdKeys.push(key);
			return {
				getGenerativeModel(config) {
					modelConfigs.push(config);
					return {
						async generateContent(payload) {
							requestPayloads.push(payload);
							return {
								response: Promise.resolve({ text: () => "generated" }),
							};
						},
					};
				},
			};
		},
	});
	const firstResult = await gateway.generateText({
		modelName: "gemini-test",
		systemInstruction: "System",
		useJsonResponse: true,
		userPrompt: "Prompt",
		attachmentParts: [{ inlineData: { data: "a", mimeType: "image/png" } }],
	});
	assert.equal(firstResult, "generated");
	assert.equal(modelConfigs[0].generationConfig.responseMimeType, "application/json");
	assert.deepEqual(requestPayloads[0][0], { text: "Prompt" });
	await gateway.generateText({
		modelName: "gemini-test",
		systemInstruction: "System",
		useJsonResponse: false,
		userPrompt: "Plain",
	});
	assert.equal(createdKeys.length, 1);
	assert.equal(requestPayloads[1], "Plain");
	apiKey = "second";
	await gateway.generateText({
		modelName: "gemini-test",
		systemInstruction: "System",
		userPrompt: "Changed key",
	});
	assert.deepEqual(createdKeys, ["first", "second"]);
});

await run(
	"AI attachment URL policies preserve collection coercion and local path safety",
	() => {
		assert.deepEqual(Object.keys(attachmentParts), [
			"buildFileParts",
			"buildImageParts",
			"collectImageUrls",
			"resolveLocalImageUrl",
		]);

		const untouchedOutput = ["existing"];
		assert.equal(collectImageUrls(null, untouchedOutput), untouchedOutput);
		assert.deepEqual(collectImageUrls(null), []);
		assert.notEqual(collectImageUrls(null), collectImageUrls(null));
		assert.equal(collectImageUrls([], null), null);
		assert.throws(() => collectImageUrls([{}], null), TypeError);

		let dynamicUrlReads = 0;
		let dynamicUrlStringReads = 0;
		const dynamicUrlItem = {
			get url() {
				dynamicUrlReads += 1;
				if (dynamicUrlReads === 1) return "/ignored-first-read.png";
				return {
					toString() {
						dynamicUrlStringReads += 1;
						return "  /api/images/кампанія/tokens/герой.png  ";
					},
				};
			},
		};
		const collected = collectImageUrls([
			{ url: "" },
			{ url: 0 },
			dynamicUrlItem,
			{ url: "  /fourth.png  " },
			{
				get url() {
					throw new Error("collection must stop at four URLs");
				},
			},
		], ["first", "second"]);
		assert.deepEqual(collected, [
			"first",
			"second",
			"/api/images/кампанія/tokens/герой.png",
			"/fourth.png",
		]);
		assert.equal(dynamicUrlReads, 2);
		assert.equal(dynamicUrlStringReads, 1);

		const alreadyFull = ["one", "two", "three", "four"];
		collectImageUrls([{ url: "five" }, { url: "six" }], alreadyFull);
		assert.deepEqual(alreadyFull, ["one", "two", "three", "four", "five"]);
		let skippedAfterFullReads = 0;
		collectImageUrls(
			[
				{},
				{
					get url() {
						skippedAfterFullReads += 1;
						return "never";
					},
				},
			],
			["one", "two", "three", "four"],
		);
		assert.equal(skippedAfterFullReads, 0);

		const imageMimeCases = new Map([
			["portrait.JPG", "image/jpeg"],
			["portrait.jpeg", "image/jpeg"],
			["portrait.PnG", "image/png"],
			["portrait.WEBP", "image/webp"],
			["portrait.gif", "image/gif"],
		]);
		for (const [fileName, mimeType] of imageMimeCases) {
			const resolved = resolveLocalImageUrl(
				`/api/images/кампанія/персонажі/портрети/${fileName}?raw=1#preview`,
			);
			assert.deepEqual(resolved, {
				filePath: path.resolve(
					storage.IMAGES_DIR,
					"кампанія",
					"персонажі",
					"портрети",
					fileName,
				),
				mimeType,
			});
		}

		assert.deepEqual(
			resolveLocalImageUrl(
				"https://example.com/api/images/campaign/tokens/hero.png?download=1",
			),
			{
				filePath: path.resolve(
					storage.IMAGES_DIR,
					"campaign",
					"tokens",
					"hero.png",
				),
				mimeType: "image/png",
			},
		);
		assert.deepEqual(
			resolveLocalImageUrl(
				"/%61pi/%69mages/campaign//tokens///hero.png",
			),
			{
				filePath: path.resolve(
					storage.IMAGES_DIR,
					"campaign",
					"tokens",
					"hero.png",
				),
				mimeType: "image/png",
			},
		);
		assert.deepEqual(
			resolveLocalImageUrl(
				"/api/images/campaign/%252e%252e/hero.png",
			),
			{
				filePath: path.resolve(
					storage.IMAGES_DIR,
					"campaign",
					"%2e%2e",
					"hero.png",
				),
				mimeType: "image/png",
			},
		);

		for (const invalidUrl of [
			"",
			"/api/images",
			"/api/images/campaign/category",
			"/API/images/campaign/category/file.png",
			"/api/IMAGES/campaign/category/file.png",
			"/api/images/campaign/category/file.svg",
			"/api/images/campaign/category/",
			"/api/images/campaign/category/../file.png",
			"/api/images/campaign/%2e%2e/other/file.png",
			"/api/images/campaign/category%2Fescape/file.png",
			"/api/images/campaign/category%5Cescape/file.png",
			"https://example.com/image.png",
		]) {
			assert.equal(resolveLocalImageUrl(invalidUrl), null);
		}
		assert.equal(resolveLocalImageUrl(Symbol("image-url")), null);
		assert.throws(
			() =>
				resolveLocalImageUrl(
					"/api/images/campaign/category/%E0%A4%A.png",
				),
			URIError,
		);

		let validStringReads = 0;
		assert.deepEqual(
			resolveLocalImageUrl({
				toString() {
					validStringReads += 1;
					return "/api/images/campaign/category/file.png";
				},
			}),
			{
				filePath: path.resolve(
					storage.IMAGES_DIR,
					"campaign",
					"category",
					"file.png",
				),
				mimeType: "image/png",
			},
		);
		assert.equal(validStringReads, 1);

		let fallbackStringReads = 0;
		assert.deepEqual(
			resolveLocalImageUrl({
				toString() {
					fallbackStringReads += 1;
					return fallbackStringReads === 1
						? "http://["
						: "/api/images/fallback/category/file.webp";
				},
			}),
			{
				filePath: path.resolve(
					storage.IMAGES_DIR,
					"fallback",
					"category",
					"file.webp",
				),
				mimeType: "image/webp",
			},
		);
		assert.equal(fallbackStringReads, 2);

		const firstCoercionError = new Error("first URL coercion failed");
		let throwingCoercionReads = 0;
		assert.deepEqual(
			resolveLocalImageUrl({
				[Symbol.toPrimitive]() {
					throwingCoercionReads += 1;
					if (throwingCoercionReads === 1) {
						throw firstCoercionError;
					}
					return "/api/images/recovered/category/file.gif";
				},
			}),
			{
				filePath: path.resolve(
					storage.IMAGES_DIR,
					"recovered",
					"category",
					"file.gif",
				),
				mimeType: "image/gif",
			},
		);
		assert.equal(throwingCoercionReads, 2);
	},
);

await run(
	"AI attachment image parts preserve MIME URL ordering size and failures",
	async () => {
		const attachmentFs = require("fs/promises");
		const originalStat = attachmentFs.stat;
		const originalReadFile = attachmentFs.readFile;
		const baseUrl = "/api/images/phase-86/tokens";
		const filePath = (name) =>
			path.resolve(storage.IMAGES_DIR, "phase-86", "tokens", name);
		const events = [];
		const readFailure = new Error("attachment image read failed");
		try {
			attachmentFs.stat = async (targetPath) => {
				const name = path.basename(targetPath);
				events.push(`stat:${name}`);
				if (name === "missing.png") {
					throw new Error("missing image");
				}
				return {
					isFile() {
						events.push(`isFile:${name}`);
						return name !== "directory.png";
					},
					get size() {
						events.push(`size:${name}`);
						if (name === "oversized.png") {
							return 10 * 1024 * 1024 + 1;
						}
						return 10 * 1024 * 1024;
					},
				};
			};
			attachmentFs.readFile = async (targetPath) => {
				const name = path.basename(targetPath);
				events.push(`read:${name}`);
				if (name === "read-error.png") throw readFailure;
				return Buffer.from(`content:${name}`, "utf8");
			};

			let declaredMimeReads = 0;
			let inlineDataReads = 0;
			const declaredInline = {
				get mimeType() {
					declaredMimeReads += 1;
					return " IMAGE/PNG ";
				},
				get name() {
					throw new Error("allowed declared MIME must skip name");
				},
				get data() {
					inlineDataReads += 1;
					return "data:image/png;base64, SGVyb8Op ";
				},
				get url() {
					throw new Error("valid inline data must skip URL");
				},
			};
			const mixedParts = await buildImageParts([
				declaredInline,
				{
					mimeType: "invalid/type",
					name: "fallback.bin",
					data: "!!!!",
					url: `  ${baseUrl}/one.png  `,
				},
				{ url: `${baseUrl}/missing.png` },
				{ url: `${baseUrl}/oversized.png` },
				{
					get mimeType() {
						throw new Error("fifth image must be capped");
					},
				},
			]);
			assert.equal(declaredMimeReads, 1);
			assert.equal(inlineDataReads, 1);
			assert.deepEqual(mixedParts, [
				{
					inlineData: {
						data: "SGVyb8Op",
						mimeType: "image/png",
					},
				},
				{
					inlineData: {
						data: Buffer.from(
							"content:one.png",
							"utf8",
						).toString("base64"),
						mimeType: "image/png",
					},
				},
			]);
			assert.deepEqual(events, [
				"stat:one.png",
				"isFile:one.png",
				"size:one.png",
				"read:one.png",
				"stat:missing.png",
				"stat:oversized.png",
				"isFile:oversized.png",
				"size:oversized.png",
			]);

			events.length = 0;
			const extensionInline = await buildImageParts([
				{
					mimeType: "not/allowed",
					name: "portrait.WEBP",
					data: "abc",
					get url() {
						throw new Error("extension inline must skip URL");
					},
				},
			]);
			assert.deepEqual(extensionInline, [
				{
					inlineData: {
						data: "abc=",
						mimeType: "image/webp",
					},
				},
			]);
			assert.deepEqual(events, []);

			events.length = 0;
			assert.deepEqual(
				await buildImageParts([
					{ url: `${baseUrl}/missing.png` },
					{ url: ` ${baseUrl}/missing.png ` },
				]),
				[],
			);
			assert.deepEqual(events, ["stat:missing.png"]);

			events.length = 0;
			assert.deepEqual(
				await buildImageParts([
					{ url: `${baseUrl}/directory.png` },
				]),
				[],
			);
			assert.deepEqual(events, [
				"stat:directory.png",
				"isFile:directory.png",
			]);

			events.length = 0;
			await assert.rejects(
				() =>
					buildImageParts([
						{ url: `${baseUrl}/read-error.png` },
					]),
				(error) => error === readFailure,
			);
			assert.deepEqual(events, [
				"stat:read-error.png",
				"isFile:read-error.png",
				"size:read-error.png",
				"read:read-error.png",
			]);

			assert.deepEqual(await buildImageParts(null), []);
			assert.deepEqual(await buildImageParts({ length: 1 }), []);
			await assert.rejects(() => buildImageParts([null]), TypeError);
			await assert.rejects(
				() =>
					buildImageParts([
						{
							mimeType: "invalid/type",
							name: "invalid.bin",
							data: "",
							url: `${baseUrl}/%E0%A4%A.png`,
						},
					]),
				URIError,
			);

			const oversizedInlineData = Buffer.alloc(
				10 * 1024 * 1024 + 1,
			).toString("base64");
			assert.deepEqual(
				await buildImageParts([
					{
						mimeType: "image/png",
						data: oversizedInlineData,
					},
				]),
				[],
			);
			assert.equal(
				filePath("one.png"),
				path.resolve(
					storage.IMAGES_DIR,
					"phase-86",
					"tokens",
					"one.png",
				),
			);
		} finally {
			attachmentFs.stat = originalStat;
			attachmentFs.readFile = originalReadFile;
		}
	},
);

await run(
	"AI attachment file parts preserve MIME data names limits and cap order",
	() => {
		assert.deepEqual(buildFileParts(null), []);
		assert.deepEqual(buildFileParts({ length: 1 }), []);
		assert.throws(() => buildFileParts([null]), TypeError);

		const textData = Buffer.from("Вміст", "utf8").toString("base64");
		const textMimeCases = new Map([
			[".csv", "text/csv"],
			[".css", "text/css"],
			[".htm", "text/html"],
			[".html", "text/html"],
			[".js", "text/javascript"],
			[".json", "application/json"],
			[".md", "text/markdown"],
			[".markdown", "text/markdown"],
			[".scss", "text/css"],
			[".txt", "text/plain"],
			[".xml", "application/xml"],
			[".yaml", "application/x-yaml"],
			[".yml", "application/x-yaml"],
		]);
		for (const [extension, mimeType] of textMimeCases) {
			const name = `Нотатки${extension.toUpperCase()}`;
			assert.deepEqual(
				buildFileParts([
					{
						name,
						mimeType: "application/pdf",
						data: textData,
					},
				]),
				[
					{
						text: `ATTACHED FILE: ${name} (${mimeType})\n\nВміст`,
					},
				],
			);
		}

		const pdfData = Buffer.from("fake pdf", "utf8").toString("base64");
		assert.deepEqual(
			buildFileParts([
				{
					name: "source.PDF",
					mimeType: "text/plain",
					data: `data:application/pdf;base64,${pdfData}`,
				},
			]),
			[
				{ text: "ATTACHED FILE: source.PDF (application/pdf)" },
				{
					inlineData: {
						data: pdfData,
						mimeType: "application/pdf",
					},
				},
			],
		);
		assert.deepEqual(
			buildFileParts([
				{
					name: "source.unknown",
					mimeType: " TEXT/XML ",
					data: textData,
				},
			]),
			[
				{
					text: "ATTACHED FILE: source.unknown (text/xml)\n\nВміст",
				},
			],
		);

		let recognizedNameReads = 0;
		let recognizedDataReads = 0;
		const recognizedFile = {
			get name() {
				recognizedNameReads += 1;
				return recognizedNameReads === 1
					? "first.JSON"
					: "  Друге\r\nім'я.JSON  ";
			},
			get mimeType() {
				throw new Error("recognized extension must skip declared MIME");
			},
			get data() {
				recognizedDataReads += 1;
				return textData;
			},
		};
		assert.deepEqual(buildFileParts([recognizedFile]), [
			{
				text: "ATTACHED FILE: Друге ім'я.JSON (application/json)\n\nВміст",
			},
		]);
		assert.equal(recognizedNameReads, 2);
		assert.equal(recognizedDataReads, 1);

		let rejectedNameReads = 0;
		let rejectedMimeReads = 0;
		let rejectedDataReads = 0;
		assert.deepEqual(
			buildFileParts([
				{
					get name() {
						rejectedNameReads += 1;
						return "source.bin";
					},
					get mimeType() {
						rejectedMimeReads += 1;
						return "invalid/type";
					},
					get data() {
						rejectedDataReads += 1;
						return textData;
					},
				},
			]),
			[],
		);
		assert.equal(rejectedNameReads, 1);
		assert.equal(rejectedMimeReads, 1);
		assert.equal(rejectedDataReads, 0);

		let invalidDataNameReads = 0;
		assert.deepEqual(
			buildFileParts([
				{
					get name() {
						invalidDataNameReads += 1;
						return "invalid.pdf";
					},
					data: "!!!!",
				},
			]),
			[],
		);
		assert.equal(invalidDataNameReads, 1);

		assert.deepEqual(
			buildFileParts([
				{ name: 0, mimeType: "application/pdf", data: "abc" },
			]),
			[
				{ text: "ATTACHED FILE: attached-file (application/pdf)" },
				{
					inlineData: {
						data: "abc=",
						mimeType: "application/pdf",
					},
				},
			],
		);
		assert.equal(
			buildFileParts([
				{
					name: " \t ",
					mimeType: "application/pdf",
					data: pdfData,
				},
			])[0].text,
			"ATTACHED FILE:  (application/pdf)",
		);

		const uppercaseDataUrl = "DATA:application/pdf;base64,SGk=";
		assert.equal(
			buildFileParts([
				{
					name: "uppercase.bin",
					mimeType: "application/pdf",
					data: uppercaseDataUrl,
				},
			])[1].inlineData.data,
			Buffer.from(uppercaseDataUrl, "base64").toString("base64"),
		);

		const oversizedFileData = Buffer.alloc(
			10 * 1024 * 1024 + 1,
		).toString("base64");
		assert.deepEqual(
			buildFileParts([
				{
					name: "oversized.pdf",
					data: oversizedFileData,
				},
			]),
			[],
		);

		const cappedFiles = Array.from({ length: 5 }, (_, index) => {
			if (index < 4) {
				return {
					name: `file-${index}.md`,
					data: textData,
				};
			}
			return {
				get name() {
					throw new Error("fifth file must be capped");
				},
			};
		});
		assert.equal(buildFileParts(cappedFiles).length, 4);
	},
);

